 const licenseQualityBatch1=[["Which enzyme is commonly used in assessment of acute pancreatitis?","Acute pancreatitis मूल्याङ्कनमा कुन enzyme प्रयोग हुन्छ?",["Lipase","ALT","ALP","CK"],0,"Serum lipase is commonly used in acute pancreatitis assessment and is relatively pancreas-specific.","Acute pancreatitis मा serum lipase प्रयोग हुन्छ र यो pancreas सँग बढी सम्बन्धित हुन्छ।","Clinical Biochemistry"],["A haemolysed blood sample may falsely increase which analyte?","Hemolysed blood sample ले कुन analyte झूटो बढाउन सक्छ?",["Potassium","Sodium in every method","Chloride always","Bicarbonate always"],0,"Red-cell lysis releases intracellular potassium and may cause a falsely increased result.","RBC फुट्दा भित्रको potassium निस्कन्छ र नतिजा झूटो बढ्न सक्छ।","Clinical Biochemistry"],["Which sample is generally used for blood gas analysis?","Blood gas analysis का लागि सामान्यतया कुन नमुना प्रयोग हुन्छ?",["Heparinised arterial blood","Clotted serum","EDTA whole blood","Urine"],0,"Blood gas testing generally uses properly collected heparinised arterial blood with prompt handling.","Blood gas परीक्षणमा heparin भएको arterial blood सही तरिकाले लिएर छिटो परीक्षण गरिन्छ।","Clinical Biochemistry"],["Which white-cell change is common in many acute bacterial infections?","धेरै acute bacterial infection मा कुन white-cell परिवर्तन देखिन्छ?",["Neutrophilia","Eosinophilia always","Basophilia always","No leukocyte change"],0,"Neutrophilia is common in many acute bacterial infections, but findings need clinical interpretation.","धेरै acute bacterial infection मा neutrophilia देखिन्छ; clinical अवस्था पनि हेर्नुपर्छ।","Haematology"],["What is the main purpose of a peripheral blood smear?","Peripheral blood smear को मुख्य उद्देश्य के हो?",["Assess blood-cell morphology","Measure serum glucose","Measure blood pH","Detect urine protein"],0,"A blood film helps assess red-cell, white-cell and platelet morphology and abnormal cells.","Blood film ले RBC, WBC र platelet को बनावट तथा असामान्य कोष हेर्न मद्दत गर्छ।","Haematology"],["Platelet clumping may cause which analyser result?","Platelet clumping हुँदा analyser मा कस्तो नतिजा आउन सक्छ?",["Falsely low platelet count","Falsely high haemoglobin","Always high WBC","No possible effect"],0,"Aggregated platelets may not be counted individually, causing pseudothrombocytopenia.","Platelet समूह बनेमा छुट्टाछुट्टै नगनिन सक्छन् र count झूटो कम देखिन सक्छ।","Haematology"],["Which medium is selective for many Gram-negative bacilli and differentiates lactose fermentation?","धेरै Gram-negative bacilli का लागि selective र lactose fermentation छुट्याउने medium कुन हो?",["MacConkey agar","Sabouraud agar","Lowenstein–Jensen medium","Loeffler serum"],0,"MacConkey agar selects many Gram-negative bacilli and differentiates lactose fermenters.","MacConkey agar ले धेरै Gram-negative bacilli छान्छ र lactose fermenter छुट्याउँछ।","Bacteriology"],["Which stain is used to demonstrate acid-fast bacilli?","Acid-fast bacilli देखाउन कुन stain प्रयोग हुन्छ?",["Ziehl–Neelsen stain","India ink","Albert stain","Lactophenol cotton blue"],0,"Ziehl–Neelsen staining demonstrates acid-fast bacilli that retain carbol fuchsin after acid-alcohol treatment.","Ziehl–Neelsen stain मा acid-alcohol पछि पनि acid-fast bacilli ले carbol fuchsin कायम राख्छन्।","Bacteriology"],["Which immunoglobulin is usually produced first in a primary immune response?","Primary immune response मा सामान्यतया सबैभन्दा पहिले कुन immunoglobulin बन्छ?",["IgM","IgG","IgA","IgE"],0,"IgM is typically the first antibody class produced in a primary immune response.","Primary immune response मा सामान्यतया सबैभन्दा पहिले IgM बन्छ।","Immunology"],["Which fixative is widely used for routine histopathology?","Routine histopathology मा व्यापक रूपमा कुन fixative प्रयोग हुन्छ?",["10% neutral buffered formalin","Distilled water","Normal saline","Glucose solution"],0,"10% neutral buffered formalin is widely used for routine tissue fixation.","Routine tissue fixation मा 10% neutral buffered formalin व्यापक रूपमा प्रयोग हुन्छ।","Histopathology"],["Which anatomical plane divides the body into right and left portions?","शरीरलाई दायाँ र बायाँ भागमा छुट्याउने anatomical plane कुन हो?",["Sagittal plane","Coronal plane","Transverse plane","Horizontal plane only"],0,"The sagittal plane divides the body into right and left portions.","Sagittal plane ले शरीरलाई दायाँ र बायाँ भागमा छुट्याउँछ।","Anatomy and Physiology"],["Which parasite is commonly associated with nocturnal periodicity of microfilariae?","Microfilariae को nocturnal periodicity कुन parasite सँग सम्बन्धित छ?",["Wuchereria bancrofti","Giardia duodenalis","Entamoeba histolytica","Taenia saginata"],0,"Many Wuchereria bancrofti infections show nocturnal periodicity; follow recommended collection timing.","Wuchereria bancrofti मा धेरैजसो nocturnal periodicity हुन्छ; नमुना संकलन समय protocol अनुसार हुनुपर्छ।","Parasitology"],["What does a spectrophotometer measure?","Spectrophotometer ले के मापन गर्छ?",["Absorbance or transmission of light","Sound frequency","Cell motility","Electrical pulse rate"],0,"A spectrophotometer measures light absorbance or transmission at selected wavelengths.","Spectrophotometer ले निश्चित wavelength मा प्रकाशको absorbance वा transmission मापन गर्छ।","Instrumentation and Automation"],["What is the purpose of internal quality control?","Internal quality control को उद्देश्य के हो?",["Monitor day-to-day analytical performance","Replace all external quality assessment","Diagnose patients directly","Avoid calibration"],0,"Internal QC monitors analytical stability and helps detect shifts or trends before reporting patient results.","Internal QC ले परीक्षणको स्थिरता जाँच्छ र बिरामीको नतिजा दिनुअघि समस्या पत्ता लगाउँछ।","Quality Control"],["Which blood component contains multiple coagulation factors?","धेरै coagulation factor कुन blood component मा हुन्छन्?",["Fresh frozen plasma","Packed red cells","Washed red cells","Platelet-poor saline"],0,"Fresh frozen plasma contains multiple coagulation factors and is used only when clinically indicated under transfusion protocols.","Fresh frozen plasma मा धेरै coagulation factor हुन्छन्; transfusion protocol अनुसार आवश्यक अवस्थामा मात्र प्रयोग हुन्छ।","Blood Banking"],["What does a direct antiglobulin test detect?","Direct antiglobulin test ले के पत्ता लगाउँछ?",["Immunoglobulin or complement attached to red cells","Platelet number","ABO gene sequence","Serum glucose"],0,"DAT detects immunoglobulin and/or complement bound to red blood cells in vivo.","DAT ले शरीरभित्र RBC मा टाँसिएको immunoglobulin र/वा complement पत्ता लगाउँछ।","Blood Banking"],["Which hormone lowers blood glucose?","रगतको glucose घटाउने hormone कुन हो?",["Insulin","Glucagon","Cortisol","Adrenaline"],0,"Insulin promotes glucose uptake and storage, lowering blood glucose concentration.","Insulin ले glucose uptake र storage बढाएर रगतको glucose घटाउँछ।","Anatomy and Physiology"],["Which organ filters plasma to form urine?","मूत्र बनाउन plasma छान्ने अंग कुन हो?",["Kidney","Liver","Spleen","Pancreas"],0,"The kidneys filter plasma and regulate water, electrolytes and waste excretion.","मिर्गौलाले plasma छानेर पानी, electrolyte र फोहोर पदार्थको निष्कासन नियमन गर्छ।","Pathology"]];
