 const questionVisualHTML=q=>q[8]?'<div class="mlt-question-visual" style="margin:12px 0;padding:10px;background:#f7fbff;border:1px solid #d8e7f2;border-radius:12px;overflow:auto">'+q[8]+'</div>':"";
 const sourceReviewHTML=q=>q[7]&&q[7].status==="reviewed"?'<p class="muted" style="margin-top:8px">✓ Source reviewed · '+esc(q[7].source)+'<br><span>'+esc(q[7].basis)+'</span> · <a href="'+esc(q[7].url)+'" target="_blank" rel="noopener">Reference</a></p>':"";
 // Clinical Biochemistry: individually checked against NIDDK and MedlinePlus references.
 const biochemistryReviewedBatch1=[
  ["What period of average blood glucose does HbA1c generally reflect?","HbA1c ले सामान्यतया कति अवधिको औसत रक्त glucose देखाउँछ?",["About the previous 3 months","Only the last 2 hours","Only the previous 24 hours","About 2 years"],0,"HbA1c measures glycated haemoglobin and reflects average blood glucose over roughly the previous 3 months. Recent weeks contribute more strongly than earlier months.","HbA1c ले glycated haemoglobin मापन गर्छ र करिब पछिल्ला ३ महिनाको औसत रक्त glucose देखाउँछ। पछिल्ला हप्ताको glucose ले अझ बढी प्रभाव पार्छ।","Clinical Biochemistry",{status:"reviewed",source:"NIDDK — The A1C Test & Diabetes",url:"https://www.niddk.nih.gov/health-information/diagnostic-tests/a1c-test/",basis:"HbA1c reflects average glucose over about 3 months"}],
  ["Which condition can make HbA1c results misleading by changing red-cell lifespan?","RBC को आयु परिवर्तन गरेर HbA1c नतिजा भ्रामक बनाउन सक्ने अवस्था कुन हो?",["Recent blood loss or haemolysis","A short period of fasting","A single high-fat meal","Mild dehydration only"],0,"HbA1c depends partly on red-cell lifespan. Recent blood loss, haemolysis, transfusion and some haemoglobin disorders can affect interpretation; use an appropriate alternative test when clinically indicated.","HbA1c RBC को आयुसँग पनि सम्बन्धित हुन्छ। हालैको रक्तस्राव, haemolysis, transfusion र केही haemoglobin disorder ले नतिजा असर गर्न सक्छन्; आवश्यक अवस्थामा उपयुक्त वैकल्पिक परीक्षण प्रयोग गरिन्छ।","Clinical Biochemistry",{status:"reviewed",source:"NIDDK — The A1C Test & Diabetes",url:"https://www.niddk.nih.gov/health-information/diagnostic-tests/a1c-test/",basis:"Factors affecting A1C accuracy"}],
  ["For a fasting plasma glucose test, how long should a person generally fast beforehand?","Fasting plasma glucose परीक्षणअघि सामान्यतया कति समय fasting गर्नुपर्छ?",["At least 8 hours","Exactly 2 hours","At least 24 hours","No fasting is ever required"],0,"For a fasting plasma glucose test, the person is generally instructed to fast for at least 8 hours; follow the laboratory and clinician's instructions.","Fasting plasma glucose परीक्षणका लागि सामान्यतया कम्तीमा ८ घण्टा fasting गर्नुपर्छ। प्रयोगशाला र चिकित्सकको निर्देशन पालना गर्नुपर्छ।","Clinical Biochemistry",{status:"reviewed",source:"NIDDK — Diabetes Tests & Diagnosis",url:"https://www.niddk.nih.gov/health-information/diabetes/overview/tests-diagnosis",basis:"Fasting plasma glucose patient preparation"}],
  ["Why is serum creatinine commonly used when estimating eGFR?","eGFR अनुमान गर्दा serum creatinine किन सामान्यतया प्रयोग गरिन्छ?",["It is a waste product that can build up when kidney filtration is reduced","It is produced only by the liver","It directly measures blood glucose","It is a pancreatic digestive enzyme"],0,"Creatinine is a muscle-related waste product cleared by the kidneys. eGFR is estimated using creatinine together with variables such as age and sex; creatinine alone does not determine eGFR.","Creatinine मांसपेशीको सामान्य metabolism बाट बन्ने waste product हो र मिर्गौलाले हटाउँछ। eGFR निकाल्दा creatinine सँग उमेर र sex जस्ता विवरण प्रयोग हुन्छन्; creatinine मात्रले eGFR निर्धारण गर्दैन।","Clinical Biochemistry",{status:"reviewed",source:"MedlinePlus — eGFR and GFR Tests",url:"https://medlineplus.gov/lab-tests/estimated-glomerular-filtration-rate-egfr-and-gfr-tests/",basis:"Creatinine and eGFR estimation"}],
  ["Which serum enzyme is commonly measured to help assess suspected acute pancreatitis?","Acute pancreatitis को शंका हुँदा मूल्याङ्कनका लागि कुन serum enzyme सामान्यतया मापन गरिन्छ?",["Lipase","ALT only","Alkaline phosphatase only","Creatine kinase only"],0,"Serum lipase is commonly used to help diagnose pancreatic disease, especially acute pancreatitis. Interpret it with symptoms, examination and other findings.","Serum lipase pancreatic रोग, विशेषगरी acute pancreatitis पहिचान गर्न सहयोगी हुन्छ। यसलाई लक्षण, परीक्षण र अन्य नतिजासँगै व्याख्या गर्नुपर्छ।","Clinical Biochemistry",{status:"reviewed",source:"MedlinePlus — Lipase Tests",url:"https://medlineplus.gov/lab-tests/lipase-tests/",basis:"Clinical use of serum lipase"}],
  ["ALT in blood is most directly associated with injury to which organ?","रगतमा ALT बढ्नु सबैभन्दा प्रत्यक्ष रूपमा कुन अंगको चोटसँग सम्बन्धित हुन्छ?",["Liver","Thyroid","Spleen","Lung"],0,"ALT is found mainly in the liver; damaged liver cells can release ALT into the bloodstream. ALT is interpreted with other liver tests and clinical context.","ALT मुख्यतः कलेजोमा पाइन्छ; कलेजोका कोषमा चोट लाग्दा ALT रगतमा निस्कन सक्छ। ALT लाई अन्य liver test र clinical अवस्थासँगै व्याख्या गर्नुपर्छ।","Clinical Biochemistry",{status:"reviewed",source:"MedlinePlus — ALT Blood Test",url:"https://medlineplus.gov/lab-tests/alt-blood-test/",basis:"ALT as a marker associated with liver-cell injury"}]
 ];
